input.command:
cd /opt/nxeon && echo "=== installed packages with lifecycle scripts ===" && node -e '
const fs=require("fs"),path=require("path");
const root="/opt/nxeon/node_modules";
const hits=[];
function scan(dir,depth){ if(depth>2) return;
 let e; try{e=fs.readdirSync(dir,{withFileTypes:true})}catch{return}
 for(const d of e){ if(!d.isDirectory()) continue;
  const p=path.join(dir,d.name);
  if(d.name.startsWith("@")){scan(p,depth);continue}
  if(d.name===".bin")continue;
  try{const pj=JSON.parse(fs.readFileSync(path.join(p,"package.json"),"utf8"));
   const s=pj.scripts||{};
   for(const k of ["preinstall","install","postinstall","prepare"]) if(s[k]) hits.push(pj.name+"@"+pj.version+"  "+k+": "+s[k].slice(0,120));
  }catch{}
  const nested=path.join(p,"node_modules"); if(fs.existsSync(nested)) scan(nested,depth+1);
 }}
scan(root,0);
console.log("count:",hits.length); hits.sort().forEach(h=>console.log("  "+h));
' 2>&1 | head -60
